def is_simple_power(x, n):
    """Returns True if x is a simple power of n, i.e., x = n**int, otherwise False."""
    if n == 1:
        return x == 1
    if x < 1:
        return False
    power = 1
    while power <= x:
        if power == x:
            return True
        power *= n
    return False
